require_once __DIR__.'/includes/functions.php';require_login();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$s=db()->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$s->execute([$id,current_user()['id']]);$order=$s->fetch();if(!$order){http_response_code(404);exit('Order not found');}$i=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$i->execute([$id]);$items=$i->fetchAll();$steps=status_steps();$status=$order['status'];$page_title='Track order';include __DIR__.'/includes/header.php'; ?>
<div class="container py-5"><span class="eyebrow">Order placed successfully</span><h1 class="section-title mt-2">Track your order</h1><p class="muted">Order #<?= e($order['order_number']) ?> · Placed <?= e(date('d M Y, h:i A',strtotime($order['created_at']))) ?></p><div class="row g-5 mt-2"><div class="col-lg-7"><div class="border p-4"><h4>Delivery progress</h4><?php $statuses=array_keys($steps);$idx=array_search($status,$statuses,true);if($status==='cancelled')$idx=-1;foreach($steps as $key=>$label):$done=$idx!==false&&$idx>=array_search($key,$statuses,true); ?><div class="track-step <?= $done?'done':'' ?>"><div class="track-dot"><?= $done?'✓':'' ?></div><div><strong><?= e($label) ?></strong><?php if($key===$status): ?><div class="small muted">Current status</div><?php endif; ?></div></div><?php endforeach; ?><?php if($status==='cancelled'): ?><div class="alert alert-warning mt-3">This order has been cancelled. Contact support for details.</div><?php endif; ?></div><div class="border p-4 mt-4"><h4>Shipping address</h4><p class="mb-1"><?= e($order['full_name']) ?> · <?= e($order['phone']) ?></p><p class="muted mb-0"><?= e($order['address']) ?>, <?= e($order['city']) ?>, <?= e($order['state']) ?> — <?= e($order['postal_code']) ?></p></div></div><div class="col-lg-5"><div class="summary-box"><h4>Items</h4><?php foreach($items as $it): ?><div class="d-flex justify-content-between gap-3 py-2"><span><?= e($it['product_name']) ?> × <?= (int)$it['quantity'] ?></span><strong><?= money($it['line_total']) ?></strong></div><?php endforeach; ?><hr><div class="d-flex justify-content-between"><span>Subtotal</span><span><?= money($order['subtotal']) ?></span></div><div class="d-flex justify-content-between"><span>Shipping</span><span><?= money($order['shipping']) ?></span></div><div class="d-flex justify-content-between"><span>Discount</span><span>−<?= money($order['discount']) ?></span></div><hr><div class="d-flex justify-content-between fw-bold fs-5"><span>Total</span><span><?= money($order['total']) ?></span></div><p class="small muted mt-3">Payment: <?= e(strtoupper($order['payment_method'])) ?> · <?= e($order['payment_status']) ?></p></div></div></div><a class="btn btn-outline-dark mt-4" href="<?= e(url('products.php')) ?>">Continue shopping</a></div>
